function BattleEndTowerNode:ShowGood(questVo, rewards, configId, isFirstQuest, lastQuestVo, lastRewards)
    local needShow = isFirstQuest
    if not isFirstQuest then
        local numChange = rewards.num ~= lastRewards.num
        local timeChange = rewards.time ~= lastRewards.time
        needShow = numChange or timeChange
    end
    KTool.SetActive(self.controller, needShow)
    KTool.SetActive(self.RT_Arrow, not isFirstQuest)
    KTool.SetActive(self.RT_OldGroup, not isFirstQuest)

    if not isFirstQuest then
        self.Txt_OldNum.text = tostring(lastRewards.num)
        self.Txt_OldDesc.text = "/"..tostring(lastRewards.time)..localize("分钟")
    end

    self.Txt_NewNum.text = tostring(rewards.num)
    self.Txt_NewDesc.text = tostring(rewards.time)..localize("分钟")

    self.STxt_NewNum.Status = isFirstQuest and 2 or ((rewards.num > lastRewards.num) and 2 or 1)
    self.STxt_NewDesc.Status = isFirstQuest and 2 or ((rewards.time < lastRewards.time) and 2 or 1)
    
    local photoPath = self:GetRewardIcon(questVo, configId)
    self.AImg_Icon:LoadSprite(photoPath)
end

function BattleEndTowerNode:ShowUpgrade(lastQuestVo, questVo, configId, delayTime)
    KTool.SetActive(self.controller, true)
    -- 显示品质提升前的奖励icon
    local photoPath = self:GetRewardIcon(lastQuestVo, configId)
    self.AImg_Icon:LoadSprite(photoPath)

    KTool.SetActive(self.RT_NormalGroup, false)
    KTool.SetActive(self.RT_UpgradeGroup, true)

    cs_coroutine.start(function()
        -- 等提升前的奖励展示完
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(delayTime))
        -- 播放切换奖励的动画
        self.Animation_Root:Play(AnimationUpgradeOut)         -- 旧奖励退出
        self.Animation_Root:PlayQueued(AnimationUpgradeIn)    -- 新奖励进入
        -- 等提升前的奖励退场之后，切换奖励图片
        local state = self.Animation_Root:get_Item(AnimationUpgradeOut)
        local duration = state.length
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(duration))
        -- 显示品质提升后的奖励icon
        local photoPath = self:GetRewardIcon(questVo, configId)
        self.AImg_Icon:LoadSprite(photoPath)
    end)
end

--- 读道具图片
function BattleEndTowerNode:GetRewardIcon(questVo, configId)
    local vo = QuestConfMgr:GetInstance():GetClimbTowerConfigVo(configId)
    local idList = string.split(vo.num, ";")
    local rewardGroupId = checkNumber(questVo.rewardGroupId) % 100
    local goodId = idList[rewardGroupId]
    if isNull(goodId) then
        goodId = idList[1]
    end
    local photoPath = GoodsConfMgr:GetInstance():GetPhotoPathById(checkNumber(goodId))
    return photoPath
end

return BattleEndTowerNode